@patch.multiple(telnetlib, Telnet=Mock())
def test_connect_controller_with_predefined_port_list(hytem_object):
    rf_paths_to_reserve = [0, 3]
    hytem_object.connect_attenuator_controller(rf_paths_at_attenuator=rf_paths_to_reserve)
    assert list(hytem_object.conns.keys()) == rf_paths_to_reserve
    assert telnetlib.Telnet.call_count == len(rf_paths_to_reserve)


@patch.multiple(telnetlib, Telnet=Mock())
def test_connect_controller_without_predefined_port_list(hytem_object):
    all_rf_paths_on_attenuator = [0, 1, 2, 3]
    hytem_object.connect_attenuator_controller()
    assert list(hytem_object.conns.keys()) == all_rf_paths_on_attenuator
    assert telnetlib.Telnet.call_count == len(all_rf_paths_on_attenuator)


def test_disconnect_controller_with_predefined_port_list(hytem_object):
    telnet_object_mock = Mock()
    rf_paths_reserved = [0, 3]
    for path in rf_paths_reserved:
        hytem_object.conns[path] = telnet_object_mock
    assert len(hytem_object.conns) == len(rf_paths_reserved)
    hytem_object.disconnect_attenuator_controller(rf_paths_at_attenuator=rf_paths_reserved)
    assert len(hytem_object.conns) == 0
    assert telnet_object_mock.close.call_count == len(rf_paths_reserved)


def test_disconnect_controller_without_predefined_port_list(hytem_object):
    telnet_object_mock = Mock()
    rf_paths_reserved = [0, 2, 3]
    for path in rf_paths_reserved:
        hytem_object.conns[path] = telnet_object_mock
    assert len(hytem_object.conns) == len(rf_paths_reserved)
    hytem_object.disconnect_attenuator_controller()
    assert len(hytem_object.conns) == 0
    assert telnet_object_mock.close.call_count == len(rf_paths_reserved)


