@patch.multiple(HytemAttenuator, _refresh_attenuator_port=Mock(), _write=Mock())
def test_method_set_single_path_attenuation_constructs_correct_command_for_hytem(hytem_object):
    rf_path_to_reserve = 1
    attenuation_value = 40
    # Additional zero is expected because Hytem takes input in three digits format
    expected_command = "ATT {} {}0".format(rf_path_to_reserve, attenuation_value)
    expected_call = [call(expected_command, rf_path_to_reserve)]
    hytem_object.reserve_port(rf_path_to_reserve)
    hytem_object._check_single_rf_path_attenuation = MagicMock(side_effect=[False, True])
    hytem_object._set_single_rf_path_decibel_attenuation(rf_path_to_reserve, attenuation_value)
    hytem_object._write.assert_has_calls(expected_call)


@patch.multiple(HytemAttenuator, _refresh_attenuator_port=Mock(), _write=Mock())
def test_method_set_single_path_attenuation_allows_retries(hytem_object):
    number_of_allowed_retries = 5
    # Adding 1, because method _check_single_rf_path_attenuation is called once before retry loop begins
    number_of_checks = number_of_allowed_retries+1
    rf_path_to_reserve = 1
    attenuation_value = 40
    retries_in_allowed_limit = [False if i < number_of_checks-1 else True for
                                i in range(number_of_checks)]
    retries_over_allowed_limit = [False if i < number_of_checks else True for
                                  i in range(number_of_checks+1)]
    hytem_object._check_single_rf_path_attenuation = MagicMock(side_effect=retries_in_allowed_limit)
    hytem_object.reserve_port(rf_path_to_reserve)
    hytem_object._set_single_rf_path_decibel_attenuation(rf_path_to_reserve, attenuation_value)
    assert hytem_object._check_single_rf_path_attenuation.call_count == number_of_checks
    hytem_object._check_single_rf_path_attenuation = MagicMock(side_effect=retries_over_allowed_limit)
    with pytest.raises(AttenuationValueIsOtherThanExpected):
        hytem_object._set_single_rf_path_decibel_attenuation(rf_path_to_reserve, attenuation_value)


@pytest.mark.parametrize("input_value,expected_output_value", [
    (0.1, '001'),
    (1, '010'),
    (10, '100'),
    (10.1, '101'),
    (99, '990'),
    (99.9, '999'),
])
def test_attenuation_value_conversion_for_hytem_success(input_value, expected_output_value, hytem_object):
        assert hytem_object._provide_correct_att_format(input_value) == expected_output_value


@pytest.mark.parametrize("number_with_decimal_part_longer_than_one_digit", [
    0.01,
    0.0001,
    1.01,
    99.99,
    ])
def test_attenuation_value_conversion_for_hytem_raises_exception_when_decimal_part_is_too_long(
        number_with_decimal_part_longer_than_one_digit,
        hytem_object):
        with pytest.raises(ValueError):
            hytem_object._provide_correct_att_format(number_with_decimal_part_longer_than_one_digit)


@pytest.mark.parametrize("number_with_integer_part_longer_than_two_digits", [
    100,
    100.1,
    ])
def test_attenuation_value_conversion_for_hytem_raises_exception_when_integer_part_is_too_long(
        number_with_integer_part_longer_than_two_digits,
        hytem_object):
        with pytest.raises(ValueError):
            hytem_object._provide_correct_att_format(number_with_integer_part_longer_than_two_digits)


